const data = $input.first().json.body || $input.first().json;
const keyword = data.keyword || '';
const content = data.content || data.article || '';
const notionPageId = data.notion_page_id || '';
const gsheetKeyword = data.keyword || '';

if (!content) throw new Error('Champ "content" manquant dans le payload');

const SYSTEM_SCORING = `Tu es schoolsWP Brain en mode Audit Scoring strict.

Contexte : schoolsWP (schoolswp.com) — WordPress pédagogique francophone.
Public : freelances et indépendants WordPress, débutants à intermédiaires.
Ton attendu : direct, tutoiement, pédagogique, sans jargon.
Mots interdits à pénaliser : disruptif, game changer, scalable, révolutionnaire, incroyable, en un clic, sans effort.

Analyse l'article et retourne UNIQUEMENT un JSON valide — aucun texte avant ni après.

CRITÈRES :

SEO (0-100) : structuration H1/H2/H3, mot-clé dans titre+intro+H2, champs sémantiques, FAQ présente, intro répondant immédiatement à l'intention.

LLM (0-100) : bloc Réponse rapide ou définition en 2-3 phrases, format Q/R explicite, entités nommées claires (plugins, versions, chiffres), phrases courtes et factuelles.

Conversion (0-100) : 1 CTA principal ciblé, lien offre/formation/affilié, argumentation ROI, tunnel logique (problème→solution→bénéfice→action), objection traitée.

Autorité (0-100) : expérience terrain (dans mon cas / j'ai testé), données chiffrées ou sources, positionnement expert non générique, comparaisons objectives, zéro promesse non prouvée.

RETOUR JSON strict :
{
  "keyword": "mot-clé détecté",
  "seo":        { "score": 0, "justification": "max 200 chars", "improvements": ["",""] },
  "llm":        { "score": 0, "justification": "max 200 chars", "improvements": ["",""] },
  "conversion": { "score": 0, "justification": "max 200 chars", "improvements": ["",""] },
  "autorite":   { "score": 0, "justification": "max 200 chars", "improvements": ["",""] },
  "score_global": 0,
  "diagnostic": "max 300 chars",
  "priority": "A|B|C"
}`;

const userMsg = keyword ? `Mot-clé cible : "${keyword}"\n\n---\n\n${content}` : content;

const openaiPayload = {
  model: 'gpt-4o',
  input: [
    { role: 'system', content: SYSTEM_SCORING },
    { role: 'user',   content: userMsg }
  ],
  temperature: 0.2,
  text: { format: { type: 'json_object' } }
};

return [{ json: { openaiPayload, keyword, notionPageId, gsheetKeyword, contentLength: content.length } }];

const resp = $input.first().json;
const prev = $('Code - Build Scoring Payload').first().json;

// Extraire le texte JSON de la Responses API
const raw = resp.output_text
  || (resp.output && resp.output[0] && resp.output[0].content && resp.output[0].content[0] && resp.output[0].content[0].text)
  || '';

if (!raw) throw new Error('Réponse OpenAI vide : ' + JSON.stringify(resp).slice(0, 300));

let scores;
try {
  scores = JSON.parse(raw);
} catch {
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('JSON non parseable : ' + raw.slice(0, 200));
  scores = JSON.parse(match[0]);
}

// Validation et recalcul Score Global
const clamp  = (v) => Math.min(100, Math.max(0, Math.round(parseFloat(v) || 0)));
const scoreSeo  = clamp(scores.seo?.score);
const scoreLlm  = clamp(scores.llm?.score);
const scoreConv = clamp(scores.conversion?.score);
const scoreAuth = clamp(scores.autorite?.score);
const scoreGlobal = Math.round((scoreSeo * 0.25) + (scoreLlm * 0.15) + (scoreConv * 0.30) + (scoreAuth * 0.30));

const action = scoreGlobal >= 95 ? '✅ Actif Premium'
  : scoreGlobal >= 85 ? '🟢 Actif Performant'
  : scoreGlobal >= 70 ? '🟡 Optimiser'
  : '🔴 Révision Stratégique';

const priority = scoreGlobal >= 85 ? 'A' : scoreGlobal >= 70 ? 'B' : 'C';

// Préparer top améliorations (les 2 dimensions les plus faibles)
const dims = [
  { key: 'SEO',        score: scoreSeo,  imps: scores.seo?.improvements  || [] },
  { key: 'LLM',        score: scoreLlm,  imps: scores.llm?.improvements  || [] },
  { key: 'Conversion', score: scoreConv, imps: scores.conversion?.improvements || [] },
  { key: 'Autorité',   score: scoreAuth, imps: scores.autorite?.improvements || [] }
].sort((a, b) => a.score - b.score);

const topImprovements = dims
  .filter(d => d.score < 85)
  .slice(0, 2)
  .flatMap(d => d.imps.slice(0, 1).map(i => `[${d.key}] ${i}`))
  .join(' | ');

const today = new Date().toISOString().split('T')[0];

return [{ json: {
  keyword:          prev.keyword || scores.keyword || '',
  notionPageId:     prev.notionPageId,
  'Score SEO':      scoreSeo,
  'Score LLM':      scoreLlm,
  'Score Conversion': scoreConv,
  'Score Autorité': scoreAuth,
  'Score Global':   scoreGlobal,
  'Action':         action,
  'Priority':       priority,
  'Diagnostic':     scores.diagnostic || '',
  topImprovements,
  'Dernière MAJ':   today,
  dims,
  needsAction:      scoreGlobal < 85,
  rawScores:        scores
} }];

const s = $input.first().json;
const sg = s['Score Global'];
const color = sg >= 70 ? 16750848 : 16711680;

const fields = [
  { name: 'Score Global', value: `**${sg}/100** — ${s.Action}`, inline: false },
  { name: 'SEO',          value: `${s['Score SEO']}/100`,        inline: true },
  { name: 'LLM',          value: `${s['Score LLM']}/100`,        inline: true },
  { name: 'Conversion',   value: `${s['Score Conversion']}/100`, inline: true },
  { name: 'Autorité',     value: `${s['Score Autorité']}/100`,   inline: true }
];

if (s.Diagnostic) fields.push({ name: 'Diagnostic', value: s.Diagnostic, inline: false });
if (s.topImprovements) fields.push({ name: 'Top améliorations', value: s.topImprovements, inline: false });

const discordPayload = {
  embeds: [{
    title:       `${s.Action} — ${s.keyword || 'Article'}`,
    description: `Score Global : **${sg}/100** · Priorité **${s.Priority}**`,
    color,
    fields,
    footer:      { text: `schoolsWP Auto-Scorer · ${s['Dernière MAJ']}` }
  }]
};

return [{ json: { discordPayload } }];

const s = $input.first().json;
return [{ json: {
  status:       'premium',
  keyword:      s.keyword,
  score_global: s['Score Global'],
  action:       s.Action
} }];
